def firstKnightTour(m, n, startRow, startCol):
    offsets = [(-2, -1), (-2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2), (2, -1), (2, 1)]
    total = m * n
    nbrs = []
    for r in range(m):
        for c in range(n):
            nbrs.append([(r + dr) * n + (c + dc) for dr, dc in offsets
                         if 0 <= r + dr < m and 0 <= c + dc < n])
    free = [len(x) for x in nbrs]           # unvisited neighbours of every cell
    seen = [False] * total
    order = []

    def go(cell, left):
        order.append(cell)
        seen[cell] = True
        if left == 0:
            return True
        for v in nbrs[cell]:
            free[v] -= 1
        found = False
        viable = True
        if left > 1:
            for v in nbrs[cell]:
                if not seen[v] and free[v] == 0:
                    viable = False
                    break
        if viable:
            for v in nbrs[cell]:
                if not seen[v] and go(v, left - 1):
                    found = True
                    break
        for v in nbrs[cell]:
            free[v] += 1
        if not found:
            seen[cell] = False
            order.pop()
        return found

    if not go(startRow * n + startCol, total - 1):
        return []
    board = [[0] * n for _ in range(m)]
    for step, cell in enumerate(order):
        board[cell // n][cell % n] = step + 1
    return board
